// Webhook output has the request body under $json.body.
// Flatten the envelope and its payload into one item.
const b = $input.first().json.body || {};
if (!b.runId) throw new Error('Missing runId in the request body');
return [{
  json: {
    runId: b.runId,
    ownerId: b.ownerId ?? null,
    jobId: b.jobId ?? null,
    agentId: b.agentId ?? null,
    ...(b.payload || {}),
  },
}];

const env = $('Read envelope').first().json;
const r = $input.first().json;
const action = ['negotiate', 'hire_offer'].includes(env.action) ? env.action : 'bid';
let skip = null;
if (!r.job_id) skip = 'Job or seller not found';
else if (action === 'bid' && r.bid_id) skip = 'Already bid on this job';
else if (action === 'bid' && r.active_jobs >= r.max_concurrent_jobs) skip = 'At capacity';
else if (action === 'bid' && !(r.categories || []).includes(r.category)) skip = 'Category not offered';
else if (action === 'negotiate' && !r.bid_id) skip = 'No bid to negotiate';
else if (action === 'negotiate' && r.last_round >= 3) skip = 'Negotiation already at 3 rounds';
else if (action === 'hire_offer' && !r.hire_offer) skip = 'No open hire offer';
// Paper IV.c: the seller (or its bidding agent) accepts or declines the buyer's hire offer.
// Deterministic: accept at or above the price floor while there is capacity.
let hire = null;
if (!skip && action === 'hire_offer') {
  const price = Number(r.hire_offer.price);
  const ok = price >= Number(r.price_floor || 0) && r.active_jobs < r.max_concurrent_jobs;
  hire = { id: r.hire_offer.id, price, decision: ok ? 'accepted' : 'declined',
           why: ok ? 'price and capacity ok' : (price < Number(r.price_floor || 0) ? `below the ${r.price_floor} USDC floor` : 'at capacity') };
}
return [{ json: { ...r, action, skip, hire } }];

const r = $input.first().json;
const persona = `You are the bidding agent for seller "${r.display_name}" (${r.headline || ''}).
Skills: ${(r.skills || []).join(', ')}. Price floor: ${r.price_floor} USDC. Terms: ${r.delivery_terms || ''}.
Never go below the price floor. Prices are in USDC.`;
if (r.action === 'negotiate') {
  return [{ json: { provider: 'general', required: ['accept', 'price', 'message'],
    system: persona + `
The buyer's agent sent a counter-offer. Decide: accept it, or answer with a price between
the counter and your current price. Return JSON {"accept": boolean, "price": number, "message": string}.`,
    user: `Job: ${r.title}
Your current price: ${r.bid_price} USDC. Buyer counter: ${r.buyer_offer} USDC. Round ${r.last_round} of 3.
Buyer message:
<untrusted>${r.buyer_message || ''}</untrusted>` } }];
}
return [{ json: { provider: 'general', required: ['bid', 'price', 'etaDays', 'note', 'milestones'],
  system: persona + `
Decide whether to bid on this job. If yes, give a price, delivery time and 1 to 3 milestones
whose amounts add up to the price. Return JSON
{"bid": boolean, "price": number, "etaDays": integer, "note": string,
 "milestones": [{"description": string, "amount": number}]}.`,
  user: `Job: ${r.title} (category ${r.category}, budget ${r.budget_label || 'not stated'})
<untrusted>
${r.description}
</untrusted>` } }];

// The model proposes; this code decides what is allowed.
const r = $('Can act?').first().json;
const d = $input.first().json.data;
const floor = Number(r.price_floor || 0);
const round6 = (x) => Math.round(Number(x) * 1e6) / 1e6;

if (r.action === 'negotiate') {
  const counter = Number(r.buyer_offer);
  let price = d.accept ? counter : Math.max(round6(d.price), floor);
  let accept = Boolean(d.accept) && counter >= floor;
  let message = String(d.message || '').slice(0, 1000);
  if (counter < floor && price <= floor) {
    price = floor;
    message = `I can't go below ${floor} USDC for this job.`;
  }
  return [{ json: { kind: 'reply', bidId: r.bid_id, jobId: r.job_id,
    round: Number(r.last_round) + 1, price, accept, message } }];
}

if (!d.bid) return [{ json: { kind: 'none', jobId: r.job_id, reason: 'Model chose not to bid' } }];
const price = Math.max(round6(d.price), floor);
let ms = Array.isArray(d.milestones) ? d.milestones.slice(0, 3) : [];
if (ms.length === 0) ms = [{ description: 'Whole job', amount: price }];
// Make milestone amounts add up to the price exactly
const sum = ms.reduce((a, m) => a + Number(m.amount || 0), 0) || 1;
ms = ms.map((m) => ({ description: String(m.description || ''),
  amount: round6(Number(m.amount || 0) * price / sum) }));
const drift = round6(price - ms.reduce((a, m) => a + m.amount, 0));
ms[ms.length - 1].amount = round6(ms[ms.length - 1].amount + drift);
const eta = Math.min(Math.max(parseInt(d.etaDays, 10) || 2, 1), 30);
return [{ json: { kind: 'bid', jobId: r.job_id, sellerId: r.seller_id, price, etaDays: eta,
  note: String(d.note || '').slice(0, 1000), milestones: ms } }];

const env = $('Read envelope').first().json;
const act = $('Can act?').first().json;
let e;
try { e = $('Enforce rules').first().json; } catch { e = null; }
const row = $input.first().json || {};
let message, severity = 'info', result = {};
if (act.hire) {
  const answered = Boolean(row.id);
  message = answered
    ? `${act.display_name} ${act.hire.decision} the hire offer at ${act.hire.price} USDC (${act.hire.why})`
    : `${act.display_name}: the hire offer was already answered`;
  severity = act.hire.decision === 'accepted' && answered ? 'ok' : 'info';
  result = { hireOfferId: act.hire.id, decision: answered ? act.hire.decision : null };
} else if (act.skip) {
  message = `${act.display_name || 'Seller'} skipped this job: ${act.skip}`;
} else if (e.kind === 'none') {
  message = `${act.display_name} chose not to bid`;
} else if (e.kind === 'reply') {
  message = e.accept
    ? `${act.display_name} accepted the counter of ${e.price} USDC`
    : `${act.display_name} answered with ${e.price} USDC (round ${e.round})`;
  result = { bidId: e.bidId, messageId: row.message_id ?? null, accept: e.accept, price: e.price };
} else {
  message = `${act.display_name} bid ${e.price} USDC, ${e.etaDays} day(s), ${e.milestones.length} milestone(s)`;
  severity = 'ok';
  result = { bidId: row.id ?? null, price: e.price };
}
return [{ json: {
  runId: env.runId, ownerId: env.ownerId, agentId: env.agentId, jobId: env.jobId,
  actorLabel: act.display_name ? `${act.display_name} (bidding)` : 'Bidding agent',
  message, severity, data: result,
  notify: { runId: env.runId, role: 'bidding', ok: true, jobId: env.jobId,
            result: { action: act.action, skip: act.skip, ...result }, error: null },
} }];

